<?php
namespace xdecaro\Component\People\Administrator\View\Dashboard;
defined('_JEXEC') or die;
use Joomla\CMS\Factory;use Joomla\CMS\Language\Text;use Joomla\CMS\MVC\View\HtmlView as BaseHtmlView;use Joomla\CMS\Toolbar\ToolbarHelper;use Joomla\Database\DatabaseInterface;use xdecaro\Component\People\Administrator\Extension\PeopleComponent;
final class HtmlView extends BaseHtmlView{public int $total=0;public function display($tpl=null):void{$app=Factory::getApplication();if(!$app->getIdentity()->authorise('core.manage','com_xdecaropeople'))throw new \RuntimeException(Text::_('JERROR_ALERTNOAUTHOR'),403);$db=Factory::getContainer()->get(DatabaseInterface::class);$q=$db->getQuery(true)->select('COUNT(*)')->from($db->quoteName('#__xdecaropeople_people'))->where($db->quoteName('state').' >= 0');$this->total=(int)$db->setQuery($q)->loadResult();$c=$app->bootComponent('com_xdecaropeople');if($c instanceof PeopleComponent)$c->getCoreIntegrationService()->enableUi($this->document->getWebAssetManager());$this->document->getWebAssetManager()->useStyle('com_xdecaropeople.admin');ToolbarHelper::title(Text::_('COM_XDECAROPEOPLE_DASHBOARD'),'users');parent::display($tpl);}}
